        { id: "hy", type: "choix", label: "Capteur hydrostatique", options: ["Envisageable", "À écarter"], attendu: 1 },
        { id: "ra", type: "choix", label: "Capteur radar", options: ["Envisageable", "À écarter"], attendu: 0 },
        { id: "us", type: "choix", label: "Capteur à ultrasons", options: ["Envisageable", "À écarter"], attendu: 0 }
